create table public.career_opportunities (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,organization text not null,role_title text not null,opportunity_type text not null check(opportunity_type in ('internship','full_time','graduate_program','public_sector','research','part_time','other')),source_name text,source_url text,location text,work_mode text,compensation_text text,recruitment_cycle text,career_direction_id uuid references public.career_directions(id) on delete set null,jd_markdown text not null default '',notes_markdown text not null default '',deadline_at timestamptz,expected_start_date date,status text not null default 'watching' check(status in ('watching','researching','preparing','closed','archived')),captured_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz);
create table public.opportunity_requirements (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,opportunity_id uuid not null references public.career_opportunities(id) on delete cascade,requirement_type text not null check(requirement_type in ('must_have','preferred','responsibility','experience','skill','credential','education','language','other')),requirement_text text not null,source_excerpt text,importance text not null default 'normal' check(importance in ('high','normal','low')),extraction_source text not null default 'human' check(extraction_source in ('human','ai_extracted')),position integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz);
create table public.resume_versions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,version_label text,content_markdown text not null default '',status text not null default 'draft' check(status in ('draft','approved','archived')),target_direction_id uuid references public.career_directions(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz);
create table public.career_applications (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,opportunity_id uuid not null references public.career_opportunities(id),resume_version_id uuid references public.resume_versions(id) on delete set null,status text not null default 'draft' check(status in ('draft','preparing','submitted','interviewing','offer','rejected','withdrawn','closed')),applied_at timestamptz,notes_markdown text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz);
create table public.resume_version_bullets (resume_version_id uuid not null references public.resume_versions(id) on delete cascade,bullet_id uuid not null references public.experience_bullets(id),user_id uuid not null references auth.users(id) on delete cascade,position integer not null default 0,primary key(resume_version_id,bullet_id));
alter table public.career_opportunities enable row level security;alter table public.opportunity_requirements enable row level security;alter table public.resume_versions enable row level security;alter table public.career_applications enable row level security;alter table public.resume_version_bullets enable row level security;
create policy "career_opportunities_own" on public.career_opportunities for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "opportunity_requirements_own" on public.opportunity_requirements for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "resume_versions_own" on public.resume_versions for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "career_applications_own" on public.career_applications for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "resume_version_bullets_own" on public.resume_version_bullets for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
